35	  const [issues, setIssues] = useState<Issue[]>([]);
36	  const [currentPage, setCurrentPage] = useState(1);
37	  const [hasMoreIssues, setHasMoreIssues] = useState(true);
38	  const [isLoading, setIsLoading] = useState(false);
39	
40	  const issuesPerPage = 30;
41	
42	  useEffect(() => {
43	    api.get(`/repos/${repositoryName}`).then((response) => {
44	      setRepository(response.data);
45	    });
46	    loadIssues(1);
47	  }, [repositoryName]);
48	
49	  const loadIssues = (page: number) => {
50	    setIsLoading(true);
51	    api
52	      .get(`/repos/${repositoryName}/issues`, {
53	        params: {
54	          page,
55	          per_page: issuesPerPage,
56	          state: 'open',
57	        },
58	      })
