88	        <RespositoryInfo>
89	          <header>
90	            <img src={repository.owner.avatar_url} alt="Owner profile avatar" />
91	            <div>
92	              <strong>{repository.full_name}</strong>
93	              <p>{repository.description}</p>
94	            </div>
95	          </header>
96	          <ul>
97	            <li>
98	              <strong>{repository.stargazers_count}</strong>
99	              <span>Stars</span>
100	            </li>
101	            <li>
102	              <strong>{repository.forks_count}</strong>
103	              <span>Forks</span>
104	            </li>
105	            <li>
106	              <strong>{repository.open_issues_count}</strong>
107	              <span>Issues abertos</span>
108	            </li>
109	          </ul>
110	        </RespositoryInfo>
111	      ) : (
