118	            <div>
119	              <strong>{issue.title}</strong>
120	              <p>{issue.user.login}</p>
121	            </div>
122	            <FiChevronRight size={20} />
123	          </a>
124	        ))}
125	        {hasMoreIssues && (
126	          <LoadMoreButton
127	            onClick={handleLoadMore}
128	            disabled={isLoading}
129	            title={isLoading ? 'Carregando...' : 'Carregar mais issues'}
130	          >
131	            {isLoading ? 'Carregando...' : 'Carregar mais'}
132	          </LoadMoreButton>
133	        )}
134	      </Issues>
135	
136	      <Footer />
137	    </>
138	  );
139	};
